3	import java.math.BigDecimal;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.web.bind.annotation.RequestBody;
6	
7	/**
8	 * {@code POST /api/lineitems} — add a line (description, qty, unit price) to an invoice and return
9	 * the created row. Wired by {@code officefloor/rest/api/lineitems.POST.yml}. The invoice must exist,
10	 * the description must be non-blank, and qty and unit price must be sensible. Adding a line changes
11	 * the invoice's total, so the invoice's derived {@code amount} is recomputed from all its lines and
12	 * stored — that is what the invoice list and dashboard read. The add is audited through {@link
13	 * Audit}.
14	 */
15	public class LineItemsPost {
16	
17	    public void service(@RequestBody NewLineItem body, LineItemRepository lineItems,
18	            InvoiceRepository invoices, Audit audit, ObjectResponse<LineItem> response) {
19	        Long invoiceId = body.getInvoiceId();
20	        Invoice invoice = invoiceId == null ? null : invoices.findById(invoiceId).orElse(null);
21	        if (invoice == null) {
22	            throw new IllegalArgumentException("a line item requires an existing invoice");
23	        }
24	        String description = body.getDescription() == null ? "" : body.getDescription().trim();
25	        if (description.isEmpty()) {
26	            throw new IllegalArgumentException("a line item requires a description");
27	        }
28	        Integer qty = body.getQty();
29	        if (qty == null || qty <= 0) {
30	            throw new IllegalArgumentException("a line item requires a positive quantity");
31	        }
32	        BigDecimal unitPrice = body.getUnitPrice();
33	        if (unitPrice == null || unitPrice.signum() < 0) {
34	            throw new IllegalArgumentException("a line item requires a non-negative unit price");
35	        }
36	        LineItem item = new LineItem();
37	        item.setInvoiceId(invoiceId);
38	        item.setDescription(description);
39	        item.setQty(qty);
40	        item.setUnitPrice(unitPrice);
41	        LineItem saved = lineItems.save(item);
42	
43	        // Recompute the invoice's derived amount from all its lines and store it, so the invoice
44	        // list (/api/invoices) and the dashboard read a correct total without re-summing.
45	        BigDecimal total = BigDecimal.ZERO;
46	        for (LineItem li : lineItems.findByInvoiceIdOrderByIdAsc(invoiceId)) {
47	            total = total.add(li.getUnitPrice().multiply(BigDecimal.valueOf(li.getQty())));
48	        }
49	        invoice.setAmount(total);
50	        invoices.save(invoice);
51	
52	        audit.record("LINE_ITEM_ADDED id=" + saved.getId() + " invoice=" + invoiceId
53	                + " description=" + saved.getDescription() + " qty=" + saved.getQty()
54	                + " unitPrice=" + saved.getUnitPrice().toPlainString());
55	        response.send(saved);
56	    }
57	}
